import { BubbleChartData } from 'components/Chart/Bubble/types';
import type { CaptionItem } from 'components/Chart/components/Legend/Legend';

export type MediaDrilldownChartEntry = {
  empty?: boolean;
  Chart?: BubbleChartData;
  Legend?: CaptionItem[];
};

export const hasMediaDrilldownChartData = (
  entry?: MediaDrilldownChartEntry,
): entry is MediaDrilldownChartEntry & { Chart: BubbleChartData } =>
  Boolean(entry && !entry.empty && entry.Chart);
